import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0032 (Archived v1): Types are Values — Universe Levels and Core Type System","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/archived/0032-types-as-values-v1-complete.md","filePath":"vendored/handl/project/adrs/archived/0032-types-as-values-v1-complete.md"}`),a={name:`handl/project/adrs/archived/0032-types-as-values-v1-complete.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0032-archived-v1-types-are-values-—-universe-levels-and-core-type-system" tabindex="-1">ADR-0032 (Archived v1): Types are Values — Universe Levels and Core Type System <a class="header-anchor" href="#adr-0032-archived-v1-types-are-values-—-universe-levels-and-core-type-system" aria-label="Permalink to “ADR-0032 (Archived v1): Types are Values — Universe Levels and Core Type System”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The handl language converged on a design where the type language and expression language are unified. Types are ordinary handl values. This required:</p><ol><li>A shared <code>Value</code> representation between runtime and typechecker</li><li>Base type families (collections) like <code>type.number</code>, <code>type.string</code>, <code>type.bool</code></li><li>Propositional equality <code>===</code> as a type, not a boolean</li><li>Membership evidence with <code>is</code> and membership assertions with <code>:</code></li><li>Universe levels (<code>Type_0</code>, <code>Type_1</code>, etc.) with cumulativity</li></ol><h2 id="decision-implemented" tabindex="-1">Decision Implemented <a class="header-anchor" href="#decision-implemented" aria-label="Permalink to “Decision Implemented”">​</a></h2><h3 id="core-features-v1-complete" tabindex="-1">Core Features (v1 Complete) <a class="header-anchor" href="#core-features-v1-complete" aria-label="Permalink to “Core Features (v1 Complete)”">​</a></h3><ol><li><strong>Shared Value representation</strong> — <code>crates/plugin-vm-type</code> defines unified <code>Value</code>/<code>Term</code> space with <code>Collection</code>, <code>Membership</code>, <code>Is</code>, <code>Eq</code>, <code>Refl</code>, <code>Empty</code></li><li><strong>Base collections</strong> — <code>type.number</code>, <code>type.string</code>, <code>type.bool</code>, <code>type.null</code>, <code>type.array</code>, <code>type.object</code>, <code>type.eq</code> in primitives</li><li><strong>Propositional equality</strong> — <code>x === y</code> is a type with <code>refl</code> when equal, empty when not</li><li><strong>Membership evidence</strong> — <code>x is T</code> produces proofs; <code>:</code> assertion binds typed names</li><li><strong>Universe levels</strong> — <code>Type_n</code> for each level n, with cumulative hierarchy and universe cumulativity in checking</li><li><strong>Dependent types</strong> — Pi (<code>∀</code>), Sigma (<code>∃</code>), and dependent pattern structures fully working</li><li><strong>NBE typechecker</strong> — Normalization-by-evaluation engine in <code>plugin-typecheck-nbe</code> and <code>plugin-engine-typecheck-nbe</code> with proper universe level handling</li></ol><h3 id="implementation-evidence" tabindex="-1">Implementation Evidence <a class="header-anchor" href="#implementation-evidence" aria-label="Permalink to “Implementation Evidence”">​</a></h3><ul><li>✅ <code>Value::Universe(Level)</code> with level arithmetic (max, succ)</li><li>✅ Typechecker universe cumulativity: <code>Type_n ⊆ Type_m</code> for <code>n ≤ m</code></li><li>✅ Universe level inference in dependent function and sigma types</li><li>✅ Tests: <code>synth_universe_and_literal</code>, <code>synth_dependent_pi</code>, <code>check_universe_cumulativity</code>, <code>universe_level_returns_zero_for_base_type</code></li><li>✅ Engine integration: <code>construct_universe</code>, <code>universe_level</code>, <code>universe_max</code> judgments</li><li>✅ Proper kind checking for type-level expressions</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>✅ Even types like <code>Even = (n: type.number) -&gt; n % 2 === 0</code> work as expected</li><li>✅ <code>Person = { name: type.string, age: type.number }</code> as record/sigma type</li><li>✅ Proper universe level inference prevents type-in-type errors</li><li>✅ Cumulative hierarchy allows code like <code>f : Type_1 -&gt; Type_2</code> to accept <code>Type_0</code> arguments</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to “See also”">​</a></h2><ul><li>ADR-0032 (Remaining) for advanced features: inductive types, dependent pattern matching, tactics, proof erasure</li><li>ADR-0054 (Generic Typecheck Engine) for the engine architecture using this value space</li><li>Crates: <code>plugin-vm-type</code>, <code>plugin-typecheck-nbe</code>, <code>plugin-engine-typecheck-nbe</code>, <code>plugin-lib-type</code></li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};